'use client';

import React, { useState, useCallback, useEffect } from 'react';
import Navbar from '../components/Navbar';
import CodePanel from '../components/CodePanel';
import MazeCanvas from '../components/MazeCanvas';
import ControlPanel from '../components/ControlPanel';
import { MazeData, Command, SimulationStats, LogEntry, Heading, RobotState } from '../types/maze';
import { generateBraidedMaze } from '../utils/mazeGenerator';
import { DEFAULT_PYTHON_CODE } from '../utils/defaultPythonCode';
import { executePythonSolver } from '../utils/pyodideRunner';
import { X, HelpCircle, ArrowRight } from 'lucide-react';

export default function Home() {
  // Layout mode: 'maze-left' (Maze on Left) or 'maze-right' (Maze on Right)
  const [layoutMode, setLayoutMode] = useState<'maze-left' | 'maze-right'>('maze-left');

  // Grid parameters
  const [gridWidth, setGridWidth] = useState(11);
  const [gridHeight, setGridHeight] = useState(11);
  const [braidRatio, setBraidRatio] = useState(0.4);
  const [simulationSpeed, setSimulationSpeed] = useState(4);

  // Maze state
  const [mazeData, setMazeData] = useState<MazeData>(() =>
    generateBraidedMaze(11, 11, 0.4)
  );

  // Editor and simulation state
  const [pythonCode, setPythonCode] = useState(DEFAULT_PYTHON_CODE);
  const [isExecutingCode, setIsExecutingCode] = useState(false);
  const [isSimulating, setIsSimulating] = useState(false);
  const [commands, setCommands] = useState<Command[]>([]);
  const [logs, setLogs] = useState<LogEntry[]>([]);
  const [showDocsModal, setShowDocsModal] = useState(false);

  // Simulation telemetry stats
  const [stats, setStats] = useState<SimulationStats>({
    stepsTaken: 0,
    collisions: 0,
    status: 'idle',
    executionTimeMs: 0,
  });

  // Append to console
  const addLog = useCallback(
    (message: string, type: LogEntry['type'] = 'info') => {
      const now = new Date();
      const timeStr =
        now.toTimeString().split(' ')[0] + '.' + String(now.getMilliseconds()).padStart(3, '0');
      setLogs((prev) => [
        ...prev,
        {
          id: Math.random().toString(36).substring(2, 9),
          type,
          message,
          timestamp: timeStr,
        },
      ]);
    },
    []
  );

  // Clear console
  const handleClearLogs = useCallback(() => {
    setLogs([]);
  }, []);

  // Regenerate maze
  const handleGenerateMaze = useCallback(() => {
    setIsSimulating(false);
    setCommands([]);
    const newMaze = generateBraidedMaze(gridWidth, gridHeight, braidRatio);
    setMazeData(newMaze);
    setStats({
      stepsTaken: 0,
      collisions: 0,
      status: 'idle',
      executionTimeMs: 0,
    });
    addLog(
      `Generated new ${gridWidth}x${gridHeight} maze (Braid Ratio: ${Math.round(
        braidRatio * 100
      )}%). Ready.`,
      'info'
    );
  }, [gridWidth, gridHeight, braidRatio, addLog]);

  // Handle grid size or braid changes
  useEffect(() => {
    handleGenerateMaze();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [gridWidth, gridHeight, braidRatio]);

  // Reset robot position
  const handleResetRobot = useCallback(() => {
    setIsSimulating(false);
    setCommands([]);
    setStats((prev) => ({
      ...prev,
      stepsTaken: 0,
      status: 'idle',
    }));
    addLog('Robot returned to start node [0, 0] facing East.', 'info');
  }, [addLog]);

  // Run simulation
  const handleRunSimulation = useCallback(async () => {
    if (isExecutingCode || isSimulating) return;

    setIsExecutingCode(true);
    setCommands([]);
    setStats((prev) => ({
      ...prev,
      status: 'idle',
      stepsTaken: 0,
    }));

    addLog('Starting Python code compilation with Pyodide...', 'info');
    const startTime = performance.now();

    const result = await executePythonSolver(pythonCode, mazeData, (msg, type) => {
      addLog(msg, type);
    });

    const elapsed = Math.round(performance.now() - startTime);
    setIsExecutingCode(false);

    if (!result.success) {
      setStats((prev) => ({
        ...prev,
        status: 'stopped',
        executionTimeMs: elapsed,
      }));
      addLog(`Execution stopped with error: ${result.error}`, 'error');
      return;
    }

    if (result.commands.length === 0) {
      setStats((prev) => ({
        ...prev,
        status: 'stopped',
        executionTimeMs: elapsed,
      }));
      addLog('solve() returned an empty list of commands.', 'warn');
      return;
    }

    addLog(
      `Algorithm generated ${result.commands.length} commands in ${elapsed}ms: [${result.commands
        .slice(0, 8)
        .join(', ')}${result.commands.length > 8 ? '...' : ''}]. Starting animation!`,
      'success'
    );

    setCommands(result.commands);
    setIsSimulating(true);
    setStats((prev) => ({
      ...prev,
      status: 'running',
      executionTimeMs: elapsed,
    }));
  }, [isExecutingCode, isSimulating, pythonCode, mazeData, addLog]);

  // Stop simulation
  const handleStopSimulation = useCallback(() => {
    setIsSimulating(false);
    setStats((prev) => ({ ...prev, status: 'stopped' }));
    addLog('Simulation stopped by user.', 'warn');
  }, [addLog]);

  // Simulation finished
  const handleSimulationEnd = useCallback(
    (status: 'success' | 'collision' | 'stopped', steps: number) => {
      setIsSimulating(false);
      setStats((prev) => ({
        ...prev,
        status,
        stepsTaken: steps,
      }));

      if (status === 'success') {
        addLog(
          `SUCCESS: Target [${mazeData.end_node.join(', ')}] reached successfully in ${steps} steps!`,
          'success'
        );
      } else if (status === 'collision') {
        addLog(`Simulation halted due to virtual wall collision.`, 'error');
      } else {
        addLog(`Simulation ended after ${steps} steps.`, 'info');
      }
    },
    [mazeData, addLog]
  );

  // Collision detected
  const handleCollision = useCallback(
    (node: [number, number], heading: Heading) => {
      setStats((prev) => ({
        ...prev,
        collisions: prev.collisions + 1,
      }));
      addLog(
        `VIRTUAL COLLISION: +5s penalty at node (${node[0]}, ${node[1]}) heading ${heading}!`,
        'error'
      );
    },
    [addLog]
  );

  // Step progress
  const handleStepProgress = useCallback(
    (step: number, _total: number, _robot: RobotState) => {
      setStats((prev) => ({
        ...prev,
        stepsTaken: step,
      }));
    },
    []
  );

  // Panel Components
  const mazeSection = (
    <section className="flex flex-col h-full space-y-3 min-h-[500px]">
      {/* 2D Canvas Visualizer */}
      <div className="flex-1 min-h-[340px] w-full relative">
        <MazeCanvas
          mazeData={mazeData}
          commands={commands}
          isSimulating={isSimulating}
          simulationSpeed={simulationSpeed}
          onSimulationEnd={handleSimulationEnd}
          onCollision={handleCollision}
          onStepProgress={handleStepProgress}
        />
      </div>

      {/* Control Panel (Sliders & Maze config) */}
      <ControlPanel
        gridWidth={gridWidth}
        gridHeight={gridHeight}
        braidRatio={braidRatio}
        simulationSpeed={simulationSpeed}
        stats={stats}
        onGridWidthChange={setGridWidth}
        onGridHeightChange={setGridHeight}
        onBraidRatioChange={setBraidRatio}
        onSimulationSpeedChange={setSimulationSpeed}
        onGenerateMaze={handleGenerateMaze}
        onResetRobot={handleResetRobot}
        isSimulating={isSimulating}
      />
    </section>
  );

  const codeSection = (
    <section className="flex flex-col h-full min-h-[500px]">
      <CodePanel
        pythonCode={pythonCode}
        onCodeChange={setPythonCode}
        onRunSimulation={handleRunSimulation}
        onStopSimulation={handleStopSimulation}
        isExecutingCode={isExecutingCode}
        isSimulating={isSimulating}
        logs={logs}
        onClearLogs={handleClearLogs}
      />
    </section>
  );

  return (
    <div className="flex flex-col min-h-screen bg-[#0a0e17] text-slate-100">
      <Navbar
        layoutMode={layoutMode}
        onToggleLayout={() =>
          setLayoutMode((prev) => (prev === 'maze-left' ? 'maze-right' : 'maze-left'))
        }
        onOpenDocs={() => setShowDocsModal(true)}
      />

      {/* Main Split Screen Area */}
      <main className="flex-1 p-3 lg:p-4 grid grid-cols-1 lg:grid-cols-2 gap-4 max-w-[1920px] w-full mx-auto h-auto lg:h-[calc(100vh-4.5rem)]">
        {layoutMode === 'maze-left' ? (
          <>
            {mazeSection}
            {codeSection}
          </>
        ) : (
          <>
            {codeSection}
            {mazeSection}
          </>
        )}
      </main>

      {/* API Reference & Instructions Modal */}
      {showDocsModal && (
        <div className="fixed inset-0 z-50 bg-black/70 backdrop-blur-sm flex items-center justify-center p-4">
          <div className="bg-[#111827] border border-slate-700 rounded-2xl max-w-2xl w-full p-6 shadow-2xl relative max-h-[90vh] overflow-y-auto">
            <button
              onClick={() => setShowDocsModal(false)}
              className="absolute top-4 right-4 text-slate-400 hover:text-white p-1 rounded-lg hover:bg-slate-800 transition-colors"
            >
              <X className="w-5 h-5" />
            </button>

            <div className="flex items-center gap-2 mb-4">
              <HelpCircle className="w-5 h-5 text-cyan-400" />
              <h2 className="text-lg font-bold text-slate-100">
                Maze Runner Controller API Guide
              </h2>
            </div>

            <div className="space-y-4 text-xs text-slate-300 leading-relaxed font-sans">
              <div>
                <h3 className="font-semibold text-cyan-400 text-sm mb-1">
                  1. The Global MAZE_DATA Object
                </h3>
                <p className="mb-2">
                  When your code runs in Pyodide WebAssembly, <code className="bg-slate-900 px-1 py-0.5 rounded text-amber-300 font-mono">MAZE_DATA</code> is provided as a global dictionary:
                </p>
                <pre className="bg-[#090d16] p-3 rounded-lg border border-slate-800 text-slate-300 font-mono text-[11px] overflow-x-auto">
{`MAZE_DATA = {
    "width": 11,               # Grid width (cols)
    "height": 11,              # Grid height (rows)
    "start_node": [0, 0],      # [x, y] coordinates
    "end_node": [10, 10],      # [x, y] coordinates
    "grid": [                  # 2D array [height][width] of bitwise walls
        [11, 5, 3, ...],
        ...
    ]
}`}
                </pre>
              </div>

              <div>
                <h3 className="font-semibold text-cyan-400 text-sm mb-1">
                  2. Bitwise Wall Encoding
                </h3>
                <p>
                  Each intersection holds a bitwise bitmask indicating which edges have virtual walls:
                </p>
                <div className="grid grid-cols-2 gap-2 mt-2 font-mono text-[11px]">
                  <div className="bg-slate-900/80 p-2 rounded border border-slate-800">
                    <span className="text-rose-400 font-bold">1</span> = NORTH Wall (y - 1)
                  </div>
                  <div className="bg-slate-900/80 p-2 rounded border border-slate-800">
                    <span className="text-rose-400 font-bold">2</span> = EAST Wall (x + 1)
                  </div>
                  <div className="bg-slate-900/80 p-2 rounded border border-slate-800">
                    <span className="text-rose-400 font-bold">4</span> = SOUTH Wall (y + 1)
                  </div>
                  <div className="bg-slate-900/80 p-2 rounded border border-slate-800">
                    <span className="text-rose-400 font-bold">8</span> = WEST Wall (x - 1)
                  </div>
                </div>
              </div>

              <div>
                <h3 className="font-semibold text-cyan-400 text-sm mb-1">
                  3. Motor Command Output
                </h3>
                <p>
                  Your <code className="bg-slate-900 px-1 py-0.5 rounded text-amber-300 font-mono">solve()</code> function must return an array of sequential commands:
                </p>
                <ul className="list-disc list-inside mt-1 space-y-1 text-slate-300 font-mono">
                  <li><span className="text-emerald-400">&apos;FORWARD&apos;</span>: Drive to the next intersection along grid line</li>
                  <li><span className="text-indigo-400">&apos;LEFT&apos;</span>: Turn 90 degrees counter-clockwise in place</li>
                  <li><span className="text-indigo-400">&apos;RIGHT&apos;</span>: Turn 90 degrees clockwise in place</li>
                  <li><span className="text-indigo-400">&apos;U_TURN&apos;</span>: Turn 180 degrees in place</li>
                </ul>
              </div>

              <div className="pt-2">
                <button
                  onClick={() => setShowDocsModal(false)}
                  className="w-full py-2 bg-cyan-600 hover:bg-cyan-500 text-white rounded-lg font-medium transition-colors cursor-pointer flex items-center justify-center gap-2"
                >
                  <span>Got it, let&apos;s code!</span>
                  <ArrowRight className="w-4 h-4" />
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}
