'use client';

import React, { useEffect, useRef, useState, useCallback } from 'react';
import { MazeData, RobotState, Command, Heading } from '../types/maze';
import { WALL_NORTH, WALL_EAST, WALL_SOUTH, WALL_WEST } from '../utils/mazeGenerator';
import confetti from 'canvas-confetti';

interface MazeCanvasProps {
  mazeData: MazeData;
  commands: Command[];
  isSimulating: boolean;
  simulationSpeed: number; // 1 to 10
  onSimulationEnd: (status: 'success' | 'collision' | 'stopped', steps: number) => void;
  onCollision: (node: [number, number], heading: Heading) => void;
  onStepProgress: (currentStep: number, totalSteps: number, robot: RobotState) => void;
}

const HEADING_ANGLES: Record<Heading, number> = {
  E: 0,
  S: Math.PI / 2,
  W: Math.PI,
  N: (3 * Math.PI) / 2,
};

const HEADING_DELTAS: Record<Heading, { dx: number; dy: number; wall: number }> = {
  N: { dx: 0, dy: -1, wall: WALL_NORTH },
  E: { dx: 1, dy: 0, wall: WALL_EAST },
  S: { dx: 0, dy: 1, wall: WALL_SOUTH },
  W: { dx: -1, dy: 0, wall: WALL_WEST },
};

export default function MazeCanvas({
  mazeData,
  commands,
  isSimulating,
  simulationSpeed,
  onSimulationEnd,
  onCollision,
  onStepProgress,
}: MazeCanvasProps) {
  const canvasRef = useRef<HTMLCanvasElement | null>(null);
  const containerRef = useRef<HTMLDivElement | null>(null);

  // Robot dynamic state for rendering
  const robotRef = useRef<{
    x: number;
    y: number;
    heading: Heading;
    angle: number;
    screenX: number | null;
    screenY: number | null;
  }>({
    x: mazeData.start_node[0],
    y: mazeData.start_node[1],
    heading: 'E',
    angle: 0,
    screenX: null,
    screenY: null,
  });

  const [collisionFlash, setCollisionFlash] = useState(false);
  const [visitedTrail, setVisitedTrail] = useState<[number, number][]>([
    [mazeData.start_node[0], mazeData.start_node[1]],
  ]);

  // Keep track of animation state
  const animFrameIdRef = useRef<number | null>(null);
  const simulationAbortRef = useRef(false);

  // Reset robot position when maze changes or simulation resets
  const resetRobot = useCallback(() => {
    robotRef.current = {
      x: mazeData.start_node[0],
      y: mazeData.start_node[1],
      heading: 'E',
      angle: 0,
      screenX: null,
      screenY: null,
    };
    setVisitedTrail([[mazeData.start_node[0], mazeData.start_node[1]]]);
    setCollisionFlash(false);
  }, [mazeData]);

  useEffect(() => {
    resetRobot();
  }, [mazeData, resetRobot]);

  // Calculate layout geometry based on logical CSS dimensions
  const getLayoutGeometry = useCallback((cssWidth: number, cssHeight: number) => {
    const cols = mazeData.width;
    const rows = mazeData.height;

    const padding = 36;
    const availW = Math.max(50, cssWidth - padding * 2);
    const availH = Math.max(50, cssHeight - padding * 2);

    const cellW = availW / (cols - 1 || 1);
    const cellH = availH / (rows - 1 || 1);
    const cellSize = Math.min(cellW, cellH);

    const totalGridW = cellSize * (cols - 1);
    const totalGridH = cellSize * (rows - 1);

    const offsetX = (cssWidth - totalGridW) / 2;
    const offsetY = (cssHeight - totalGridH) / 2;

    const getNodePos = (nx: number, ny: number) => ({
      x: offsetX + nx * cellSize,
      y: offsetY + ny * cellSize,
    });

    return { cellSize, offsetX, offsetY, getNodePos };
  }, [mazeData]);

  // Draw maze & robot on canvas
  const drawScene = useCallback(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const dpr = window.devicePixelRatio || 1;
    const rect = canvas.getBoundingClientRect();
    const cssWidth = Math.floor(rect.width) || canvas.clientWidth || 400;
    const cssHeight = Math.floor(rect.height) || canvas.clientHeight || 400;

    // Ensure high-DPI resolution without double-scaling
    const targetW = Math.floor(cssWidth * dpr);
    const targetH = Math.floor(cssHeight * dpr);
    if (canvas.width !== targetW || canvas.height !== targetH) {
      canvas.width = targetW;
      canvas.height = targetH;
    }

    // Reset transform matrix and scale by devicePixelRatio
    ctx.setTransform(1, 0, 0, 1, 0, 0);
    ctx.scale(dpr, dpr);

    // Clear background
    ctx.clearRect(0, 0, cssWidth, cssHeight);
    ctx.fillStyle = '#0d131f';
    ctx.fillRect(0, 0, cssWidth, cssHeight);

    const cols = mazeData.width;
    const rows = mazeData.height;
    const { cellSize, getNodePos } = getLayoutGeometry(cssWidth, cssHeight);

    // 1. Draw physical grid lines (interconnected robotics tracks)
    ctx.strokeStyle = '#1e293b';
    ctx.lineWidth = 2;
    ctx.lineCap = 'round';

    for (let y = 0; y < rows; y++) {
      for (let x = 0; x < cols; x++) {
        const p1 = getNodePos(x, y);
        if (x < cols - 1) {
          const p2 = getNodePos(x + 1, y);
          ctx.beginPath();
          ctx.moveTo(p1.x, p1.y);
          ctx.lineTo(p2.x, p2.y);
          ctx.stroke();
        }
        if (y < rows - 1) {
          const p2 = getNodePos(x, y + 1);
          ctx.beginPath();
          ctx.moveTo(p1.x, p1.y);
          ctx.lineTo(p2.x, p2.y);
          ctx.stroke();
        }
      }
    }

    // 2. Draw robot traveled trail
    if (visitedTrail.length > 1) {
      ctx.strokeStyle = 'rgba(6, 182, 212, 0.45)';
      ctx.lineWidth = Math.max(3, cellSize * 0.12);
      ctx.lineJoin = 'round';
      ctx.lineCap = 'round';
      ctx.beginPath();
      const first = getNodePos(visitedTrail[0][0], visitedTrail[0][1]);
      ctx.moveTo(first.x, first.y);
      for (let i = 1; i < visitedTrail.length; i++) {
        const pt = getNodePos(visitedTrail[i][0], visitedTrail[i][1]);
        ctx.lineTo(pt.x, pt.y);
      }
      ctx.stroke();
    }

    // 3. Draw grid intersection nodes (track points)
    const nodeRadius = Math.max(2.5, Math.min(4.5, cellSize * 0.08));
    for (let y = 0; y < rows; y++) {
      for (let x = 0; x < cols; x++) {
        const { x: px, y: py } = getNodePos(x, y);
        ctx.fillStyle = '#334155';
        ctx.beginPath();
        ctx.arc(px, py, nodeRadius, 0, Math.PI * 2);
        ctx.fill();
      }
    }

    // 4. Draw Start and End target nodes
    const startPos = getNodePos(mazeData.start_node[0], mazeData.start_node[1]);
    const endPos = getNodePos(mazeData.end_node[0], mazeData.end_node[1]);
    const beaconRadius = Math.max(8, Math.min(14, cellSize * 0.28));

    // Start Beacon (Green)
    ctx.save();
    ctx.shadowColor = '#10b981';
    ctx.shadowBlur = 10;
    ctx.fillStyle = '#10b981';
    ctx.beginPath();
    ctx.arc(startPos.x, startPos.y, beaconRadius, 0, Math.PI * 2);
    ctx.fill();
    ctx.fillStyle = '#ffffff';
    ctx.beginPath();
    ctx.arc(startPos.x, startPos.y, beaconRadius * 0.45, 0, Math.PI * 2);
    ctx.fill();
    ctx.restore();

    // End Beacon (Cyan/Blue Target)
    ctx.save();
    ctx.shadowColor = '#06b6d4';
    ctx.shadowBlur = 12;
    ctx.strokeStyle = '#06b6d4';
    ctx.lineWidth = 3;
    ctx.beginPath();
    ctx.arc(endPos.x, endPos.y, beaconRadius * 1.2, 0, Math.PI * 2);
    ctx.stroke();

    ctx.fillStyle = '#3b82f6';
    ctx.beginPath();
    ctx.arc(endPos.x, endPos.y, beaconRadius * 0.8, 0, Math.PI * 2);
    ctx.fill();

    // Checkered center dot
    ctx.fillStyle = '#f8fafc';
    ctx.beginPath();
    ctx.arc(endPos.x, endPos.y, beaconRadius * 0.35, 0, Math.PI * 2);
    ctx.fill();
    ctx.restore();

    // 5. Draw Virtual Walls (Thick Red Obstacles)
    ctx.save();
    ctx.strokeStyle = '#f43f5e';
    ctx.lineWidth = Math.max(4, Math.min(8, cellSize * 0.2));
    ctx.lineCap = 'round';
    ctx.shadowColor = 'rgba(244, 63, 94, 0.7)';
    ctx.shadowBlur = 6;

    for (let y = 0; y < rows; y++) {
      for (let x = 0; x < cols; x++) {
        const wallMask = mazeData.grid[y][x];
        const p1 = getNodePos(x, y);

        // East wall
        if (wallMask & WALL_EAST && x < cols - 1) {
          const p2 = getNodePos(x + 1, y);
          ctx.beginPath();
          ctx.moveTo(p1.x, p1.y);
          ctx.lineTo(p2.x, p2.y);
          ctx.stroke();
        }

        // South wall
        if (wallMask & WALL_SOUTH && y < rows - 1) {
          const p2 = getNodePos(x, y + 1);
          ctx.beginPath();
          ctx.moveTo(p1.x, p1.y);
          ctx.lineTo(p2.x, p2.y);
          ctx.stroke();
        }
      }
    }
    ctx.restore();

    // 6. Draw Robot
    const robot = robotRef.current;
    const robotScreenPos = getNodePos(robot.x, robot.y);
    const drawX = robot.screenX !== null ? robot.screenX : robotScreenPos.x;
    const drawY = robot.screenY !== null ? robot.screenY : robotScreenPos.y;

    ctx.save();
    ctx.translate(drawX, drawY);
    ctx.rotate(robot.angle);

    const robotRadius = Math.max(9, Math.min(18, cellSize * 0.35));

    // Glow under robot
    ctx.shadowColor = '#06b6d4';
    ctx.shadowBlur = 10;

    // Robot body
    ctx.fillStyle = '#0284c7';
    ctx.beginPath();
    ctx.roundRect(-robotRadius, -robotRadius * 0.8, robotRadius * 2, robotRadius * 1.6, 4);
    ctx.fill();

    // Tread lines
    ctx.fillStyle = '#0f172a';
    ctx.fillRect(-robotRadius * 0.9, -robotRadius * 0.9, robotRadius * 1.8, 3);
    ctx.fillRect(-robotRadius * 0.9, robotRadius * 0.9 - 3, robotRadius * 1.8, 3);

    // Front sensor dome
    ctx.fillStyle = '#38bdf8';
    ctx.beginPath();
    ctx.arc(robotRadius * 0.3, 0, robotRadius * 0.45, 0, Math.PI * 2);
    ctx.fill();

    // Direction Arrow Pointer
    ctx.fillStyle = '#f8fafc';
    ctx.beginPath();
    ctx.moveTo(robotRadius * 0.85, 0);
    ctx.lineTo(robotRadius * 0.2, -robotRadius * 0.35);
    ctx.lineTo(robotRadius * 0.35, 0);
    ctx.lineTo(robotRadius * 0.2, robotRadius * 0.35);
    ctx.closePath();
    ctx.fill();

    ctx.restore();
  }, [mazeData, visitedTrail, getLayoutGeometry]);

  // Robust Resize Observer for full responsiveness
  useEffect(() => {
    const container = containerRef.current;
    if (!container) return;

    const ro = new ResizeObserver(() => {
      drawScene();
    });

    ro.observe(container);
    drawScene();

    return () => ro.disconnect();
  }, [drawScene]);

  // Redraw when scene changes
  useEffect(() => {
    drawScene();
  }, [drawScene]);

  // Heading helper
  const turnHeading = (current: Heading, command: 'LEFT' | 'RIGHT' | 'U_TURN'): Heading => {
    const headings: Heading[] = ['N', 'E', 'S', 'W'];
    const idx = headings.indexOf(current);
    if (command === 'LEFT') return headings[(idx + 3) % 4];
    if (command === 'RIGHT') return headings[(idx + 1) % 4];
    if (command === 'U_TURN') return headings[(idx + 2) % 4];
    return current;
  };

  // Execution Loop
  useEffect(() => {
    if (!isSimulating || commands.length === 0) {
      simulationAbortRef.current = true;
      if (animFrameIdRef.current) {
        cancelAnimationFrame(animFrameIdRef.current);
      }
      return;
    }

    simulationAbortRef.current = false;
    let stepIndex = 0;

    const baseDuration = Math.max(50, 600 / Math.max(1, simulationSpeed));

    const canvas = canvasRef.current;
    if (!canvas) return;

    const rect = canvas.getBoundingClientRect();
    const cssWidth = Math.floor(rect.width) || canvas.clientWidth || 400;
    const cssHeight = Math.floor(rect.height) || canvas.clientHeight || 400;
    const { cellSize, getNodePos } = getLayoutGeometry(cssWidth, cssHeight);
    const cols = mazeData.width;
    const rows = mazeData.height;

    const executeNextStep = () => {
      if (simulationAbortRef.current) return;

      if (stepIndex >= commands.length) {
        const finalX = robotRef.current.x;
        const finalY = robotRef.current.y;
        const reachedTarget =
          finalX === mazeData.end_node[0] && finalY === mazeData.end_node[1];

        if (reachedTarget) {
          confetti({
            particleCount: 80,
            spread: 70,
            origin: { y: 0.6 },
          });
          onSimulationEnd('success', stepIndex);
        } else {
          onSimulationEnd('stopped', stepIndex);
        }
        return;
      }

      const cmd = commands[stepIndex];
      const startRobot = { ...robotRef.current };
      onStepProgress(stepIndex + 1, commands.length, {
        x: startRobot.x,
        y: startRobot.y,
        heading: startRobot.heading,
      });

      if (cmd === 'FORWARD') {
        const delta = HEADING_DELTAS[startRobot.heading];
        const nextX = startRobot.x + delta.dx;
        const nextY = startRobot.y + delta.dy;

        // Collision Check: Virtual wall between current node and target
        const currentWallMask = mazeData.grid[startRobot.y][startRobot.x];
        const hasWall = (currentWallMask & delta.wall) !== 0;
        const isOutOfBounds = nextX < 0 || nextX >= cols || nextY < 0 || nextY >= rows;

        if (hasWall || isOutOfBounds) {
          setCollisionFlash(true);
          onCollision([startRobot.x, startRobot.y], startRobot.heading);

          const bumpStartTime = performance.now();
          const bumpDuration = 200;

          const animateBump = (now: number) => {
            const elapsed = now - bumpStartTime;
            const progress = Math.min(1, elapsed / bumpDuration);
            const bumpOffset = Math.sin(progress * Math.PI) * (cellSize * 0.25);

            const curPos = getNodePos(startRobot.x, startRobot.y);
            robotRef.current.screenX = curPos.x + delta.dx * bumpOffset;
            robotRef.current.screenY = curPos.y + delta.dy * bumpOffset;
            drawScene();

            if (progress < 1) {
              requestAnimationFrame(animateBump);
            } else {
              robotRef.current.screenX = null;
              robotRef.current.screenY = null;
              drawScene();
              setTimeout(() => {
                setCollisionFlash(false);
                onSimulationEnd('collision', stepIndex + 1);
              }, 300);
            }
          };

          requestAnimationFrame(animateBump);
          return;
        }

        // Smooth Forward Translation
        const fromPos = getNodePos(startRobot.x, startRobot.y);
        const toPos = getNodePos(nextX, nextY);
        const startTime = performance.now();

        const animateMove = (now: number) => {
          if (simulationAbortRef.current) return;
          const elapsed = now - startTime;
          const progress = Math.min(1, elapsed / baseDuration);
          const ease = progress;

          robotRef.current.screenX = fromPos.x + (toPos.x - fromPos.x) * ease;
          robotRef.current.screenY = fromPos.y + (toPos.y - fromPos.y) * ease;
          drawScene();

          if (progress < 1) {
            animFrameIdRef.current = requestAnimationFrame(animateMove);
          } else {
            robotRef.current.x = nextX;
            robotRef.current.y = nextY;
            robotRef.current.screenX = null;
            robotRef.current.screenY = null;
            setVisitedTrail((prev) => [...prev, [nextX, nextY]]);
            drawScene();

            stepIndex++;
            setTimeout(executeNextStep, 20);
          }
        };

        animFrameIdRef.current = requestAnimationFrame(animateMove);
      } else {
        // Rotation (LEFT, RIGHT, U_TURN)
        const nextHeading = turnHeading(startRobot.heading, cmd);
        const startAngle = robotRef.current.angle;
        let deltaAngle = 0;

        if (cmd === 'RIGHT') deltaAngle = Math.PI / 2;
        else if (cmd === 'LEFT') deltaAngle = -Math.PI / 2;
        else if (cmd === 'U_TURN') deltaAngle = Math.PI;

        const startTime = performance.now();
        const rotDuration = baseDuration * 0.7;

        const animateTurn = (now: number) => {
          if (simulationAbortRef.current) return;
          const elapsed = now - startTime;
          const progress = Math.min(1, elapsed / rotDuration);

          robotRef.current.angle = startAngle + deltaAngle * progress;
          drawScene();

          if (progress < 1) {
            animFrameIdRef.current = requestAnimationFrame(animateTurn);
          } else {
            robotRef.current.heading = nextHeading;
            robotRef.current.angle = HEADING_ANGLES[nextHeading];
            drawScene();

            stepIndex++;
            setTimeout(executeNextStep, 20);
          }
        };

        animFrameIdRef.current = requestAnimationFrame(animateTurn);
      }
    };

    executeNextStep();

    return () => {
      simulationAbortRef.current = true;
      if (animFrameIdRef.current) {
        cancelAnimationFrame(animFrameIdRef.current);
      }
    };
  }, [
    isSimulating,
    commands,
    simulationSpeed,
    mazeData,
    drawScene,
    getLayoutGeometry,
    onSimulationEnd,
    onCollision,
    onStepProgress,
  ]);

  return (
    <div
      ref={containerRef}
      className={`relative w-full h-full min-h-[320px] rounded-xl overflow-hidden border border-slate-800 bg-[#0d131f] flex items-center justify-center transition-colors duration-300 ${
        collisionFlash ? 'ring-4 ring-rose-500 shadow-[0_0_30px_rgba(244,63,94,0.6)]' : ''
      }`}
    >
      <canvas ref={canvasRef} className="block w-full h-full" />

      {/* Collision Overlay Flash */}
      {collisionFlash && (
        <div className="absolute inset-0 bg-rose-600/30 backdrop-blur-[1px] pointer-events-none flex items-center justify-center animate-pulse">
          <div className="bg-rose-950/90 border border-rose-500 text-rose-200 px-6 py-3 rounded-xl shadow-2xl font-bold tracking-wider text-sm flex items-center gap-2">
            <span className="text-xl">💥</span>
            <span>VIRTUAL COLLISION DETECTED! (+5s penalty)</span>
          </div>
        </div>
      )}

      {/* Legend Badge Overlay */}
      <div className="absolute top-3 left-3 bg-slate-900/85 backdrop-blur-md border border-slate-800 text-[11px] px-3 py-1.5 rounded-lg flex items-center gap-4 text-slate-300 shadow-lg pointer-events-none z-10">
        <div className="flex items-center gap-1.5">
          <span className="w-2.5 h-2.5 rounded-full bg-emerald-500 ring-2 ring-emerald-500/30" />
          <span>Start (0,0)</span>
        </div>
        <div className="flex items-center gap-1.5">
          <span className="w-2.5 h-2.5 rounded-full bg-cyan-500 ring-2 ring-cyan-500/30" />
          <span>End ({mazeData.width - 1},{mazeData.height - 1})</span>
        </div>
        <div className="flex items-center gap-1.5">
          <span className="w-3.5 h-1 bg-rose-500 rounded-full" />
          <span>Virtual Wall</span>
        </div>
      </div>
    </div>
  );
}
